function paginate(total,page,pageSize,onPage){const pages=Math.max(1,Math.ceil(total/pageSize)),safe=Math.min(page,pages);let html=`<button data-page="${Math.max(1,safe-1)}">‹</button>`;for(let i=1;i<=pages;i++){if(pages>7&&i>2&&i<pages-1&&Math.abs(i-safe)>1){if(i===3||i===pages-2)html+='<span>…</span>';continue}html+=`<button class="${i===safe?'active':''}" data-page="${i}">${i}</button>`}html+=`<button data-page="${Math.min(pages,safe+1)}">›</button>`;setTimeout(()=>aqq('[data-page]').forEach(b=>{if(b.closest('#productPagination'))b.onclick=()=>{productPage=+b.dataset.page;renderProducts()};if(b.closest('#orderPagination'))b.onclick=()=>{orderPage=+b.dataset.page;renderOrders()};if(b.closest('#inventoryPagination'))b.onclick=()=>{inventoryPage=+b.dataset.page;renderInventory()}}));return html}

