function orderChannel(o){const channels=['Online mağaza','Trendyol','Hepsiburada','Amazon'],n=+String(o.id).replace(/\D/g,'')||0;return channels[n%channels.length]}
function orderMatchesTab(o){if(orderTab==='all')return true;if(orderTab==='unfulfilled')return!['Gönderildi','Teslim edildi','İptal'].includes(o.status);if(orderTab==='unpaid')return o.payment!=='Ödendi';if(orderTab==='open')return!['Teslim edildi','İptal'].includes(o.status);if(orderTab==='closed')return['Teslim edildi','İptal'].includes(o.status);if(orderTab==='local')return o.city==='İstanbul';return true}
