function filteredProducts(){const q=aq('#productSearch').value.toLocaleLowerCase('tr'),cat=aq('#productCategoryFilter').value,stock=aq('#productStockFilter').value;return adminProducts.filter(p=>{const s=totalStock(p),active=p.active!==false;if(productTab==='active'&&!active)return false;if(productTab==='draft'&&active)return false;if(productTab==='low'&&s>=20)return false;if(cat!=='all'&&p.category!==cat)return false;if(stock==='in'&&s<=0)return false;if(stock==='low'&&(s<=0||s>=20))return false;if(stock==='out'&&s>0)return false;return!q||`${p.name} ${p.category} ${p.variants?.map(v=>v.sku).join(' ')}`.toLocaleLowerCase('tr').includes(q)}).sort((a,b)=>b.id-a.id)}
