function cacheProduct(product){
  if(product.id>=1000){
    const custom=readJSON('viento-admin-custom-products',[]),idx=custom.findIndex(x=>x.id===product.id);
    idx>=0?custom[idx]=product:custom.push(product);
    localStorage.setItem('viento-admin-custom-products',JSON.stringify(custom));
    return;
  }
  const overrides=readJSON('viento-admin-overrides',{});
  overrides[product.id]={name:product.name,category:product.category,image:product.image,media:product.media,price:product.price,oldPrice:product.oldPrice,active:product.active,badge:product.badge,material:product.material,dimensions:product.dimensions,desc:product.desc,variants:product.variants,barcode:product.barcode,hsCode:product.hsCode,weight:product.weight,desi:product.desi,origin:product.origin,leadTime:product.leadTime,assembly:product.assembly,channels:product.channels,productType:product.productType,vendor:product.vendor,tags:product.tags,seoTitle:product.seoTitle,seoDescription:product.seoDescription,slug:product.slug,publishDate:product.publishDate,collectionYear:product.collectionYear,warranty:product.warranty,care:product.care,metafields:product.metafields};
  localStorage.setItem('viento-admin-overrides',JSON.stringify(overrides));
}
async function persistProduct(product){
  product.active=product.active!==false;
  if(window.VientoDB)await window.VientoDB.saveProduct(product);
  cacheProduct(product);
  return product;
}
