function productMediaUrls(product){return[...new Set([...(Array.isArray(product?.media)?product.media:[]),product?.image,...(product?.variants||[]).map(variant=>variant.image)].filter(Boolean))]}
function setEditorSaveState(message,type=''){const state=aq('#editorSaveState');state.textContent=message;state.className=type?`editor-save-state ${type}`:'editor-save-state'}
