  aqq('[data-remove-variant]').forEach(button=>button.onclick=()=>{collectVariantInputs();if(editingVariants.length===1)return toast('En az bir renk varyasyonu gerekli');editingVariants.splice(+button.dataset.removeVariant,1);renderVariantEditor(editingVariants)});
