function renderCustomMetafields(fields=[]){aq('#customMetafields').innerHTML=fields.map((field,i)=>`<div class="custom-metafield-row"><input data-meta-key="${i}" value="${field.key||''}" placeholder="Alan adı" aria-label="Özel alan adı"><input data-meta-value="${i}" value="${field.value||''}" placeholder="Değer" aria-label="Özel alan değeri"><button type="button" data-remove-meta="${i}" aria-label="Alanı kaldır">×</button></div>`).join('');aqq('[data-remove-meta]').forEach(button=>button.onclick=()=>{const fields=readMetafields();fields.splice(+button.dataset.removeMeta,1);renderCustomMetafields(fields)})}
