async function uploadProductMedia(files){
  const chosen=[...files];if(!chosen.length)return;
  if(mediaUploadInProgress)return toast('Devam eden medya yüklemesi var');
  if(editingMedia.length+chosen.length>12)return toast('Bir üründe en fazla 12 medya görseli olabilir');
  const invalid=chosen.find(file=>!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>10*1024*1024);
  if(invalid)return toast(`${invalid.name}: yalnızca JPEG, PNG, WebP ve en fazla 10 MB desteklenir`);
  mediaUploadInProgress=true;const progress=aq('#mediaUploadProgress');progress.className='media-upload-progress active';setEditorSaveState('Fotoğraflar Supabase Storage’a yükleniyor…','saving');
  let uploaded=0;
  try{
    for(const file of chosen){
      progress.innerHTML=`<span style="--progress:${Math.round(uploaded/chosen.length*100)}%"></span><b>${uploaded+1}/${chosen.length} · ${adminSafe(file.name)} yükleniyor</b>`;
      const url=await window.VientoDB.uploadCatalogImage(file,editingProductToken,`media-${editingMedia.length+1}`);
      if(!editingMedia.includes(url))editingMedia.push(url);if(!uploadedImage)uploadedImage=url;uploaded++;renderMediaLibrary();
    }
    progress.innerHTML=`<span style="--progress:100%"></span><b>${uploaded} fotoğraf başarıyla yüklendi</b>`;progress.classList.add('success');setEditorSaveState('Medya hazır; fotoğrafları renk varyasyonlarına atayın','success');toast(`${uploaded} gerçek ürün fotoğrafı medya havuzuna eklendi`);
  }catch(error){
    console.error(error);progress.classList.add('error');progress.innerHTML=`<b>Yükleme durdu: ${adminSafe(error.message)}</b>`;setEditorSaveState(`Medya yüklenemedi: ${error.message}`,'error');toast(`Fotoğraf yüklenemedi: ${error.message}`);
  }finally{mediaUploadInProgress=false;aq('#productMediaFiles').value=''}
}
